#ifndef __HUD_CATALOG_H__
#define __HUD_CATALOG_H__

// The race HUD's catalog (src/hud_catalog.cpp, docs/hud_layout.md#catalog): every part the race HUD can draw, where
// the game draws it in each layout and where it can move, from the game's layout tables and callbacks (the ROM's,
// src/hud_catalog_rom.inc, generated by tools/hud_preview) and the recomp's own HUD elements. The layout engine
// (src/hud_layout.cpp) places elements by the catalog alone, so the previewer (tools/hud_preview) knows exactly where
// everything goes without the game, and the game checks every widget it draws against its catalog part
// (src/hud.cpp): a widget with no part, or drawn outside its part's reach, is reported.

#include <cstdint>
#include <string>
#include <vector>

namespace rush2::hud_catalog {
    // What a part of the race HUD is part of: a player's time, speedometer... or a shared one (the track map, the
    // time left). LapTime is the checkpoint (lap) time box under the race time; StuntScore and StuntTrick a player's
    // stunt panel boxes (BEST / TOTAL, and the trick name while one scores); Message a banner that comes and goes over
    // the view (WRONG WAY and its arrows, BONUS TIME, GAME OVER); Banner a player's place once finished; Deaths the
    // DEATHS option's skull; It the stunt mode's IT badge; Odometer Rush 2049's odometer (src/rush2049/odometer.cpp);
    // LapsLeft the finish flag and laps-left number on the track map.
    enum class Role : uint8_t {
        Other, Time, Speed, Position, Radar, Banner, Deaths, TimeLeft, Map, Tach, Gear, StuntScore, StuntTrick,
        LapTime, Message, Odometer, LapsLeft, It,
        // Rush 2049's battle HUD (src/rush2049/battle.cpp; no Rush 2 widgets: the engine places them as 2049 does):
        // the health bar, the weapon held with its ammo, the coin with the kill count, the power-up in effect.
        BattleBar, BattleWeapon, BattleCoin, BattlePowerup, Count
    };
    const char* role_name(Role role);

    // Inclusive bounds in 4:3 screen pixels (320 x 240). Empty when x0 > x1.
    struct Rect {
        int32_t x0 = INT32_MAX, y0 = INT32_MAX, x1 = INT32_MIN, y1 = INT32_MIN;
        bool valid() const { return x0 <= x1 && y0 <= y1; }
        int32_t w() const { return x1 - x0 + 1; }
        int32_t h() const { return y1 - y0 + 1; }
        void add(const Rect& r) {
            if (!r.valid()) return;
            x0 = x0 < r.x0 ? x0 : r.x0;
            y0 = y0 < r.y0 ? y0 : r.y0;
            x1 = x1 > r.x1 ? x1 : r.x1;
            y1 = y1 > r.y1 ? y1 : r.y1;
        }
        Rect moved(int32_t dx, int32_t dy) const { return valid() ? Rect{ x0 + dx, y0 + dy, x1 + dx, y1 + dy } : *this; }
        bool overlaps(const Rect& r) const { return valid() && r.valid() && x0 <= r.x1 && r.x0 <= x1 && y0 <= r.y1 && r.y0 <= y1; }
        bool contains(int32_t x, int32_t y, int32_t margin = 0) const {
            return valid() && x >= x0 - margin && x <= x1 + margin && y >= y0 - margin && y <= y1 + margin;
        }
        bool contains(const Rect& r) const { return valid() && r.valid() && r.x0 >= x0 && r.x1 <= x1 && r.y0 >= y0 && r.y1 <= y1; }
        bool operator==(const Rect&) const = default;
    };

    // How the game built a widget, as it was built (before the element's callback first ran: callbacks zero
    // themselves for players who aren't racing and keep their state in the parameter).
    struct Identity {
        enum class Kind : uint8_t { None, Entry, Box } kind = Kind::None;
        char name[16] = {};       // Entry: the image's name ("" none, "-1" a callback widget that only prints)
        int16_t x = 0, y = 0;     // Entry: the entry's position; Box: its top left corner
        int16_t x1 = 0, y1 = 0;   // Box: its bottom right corner
        uint32_t callback = 0, param = 0;
        int8_t part = -1;         // Box: 0 the top edge, 1 the left edge, 2 the fill, 3 the right edge, 4 the bottom
    };

    enum class Kind : uint8_t {
        Image,  // a layout entry's image (or a cell of it)
        Fill,   // a box's fill or edge
        Text,   // text a callback prints
        Code,   // drawn by the recomp's own code (the odometer, the battle HUD)
    };

    // One thing the HUD draws.
    // The messages' groups (Part::group of Role::Message): WRONG WAY with its arrows, BONUS TIME, GAME OVER.
    constexpr uint8_t message_wrong_way = 1, message_bonus = 5, message_game_over = 6;

    struct Part {
        Kind kind = Kind::Image;
        Role role = Role::Other;
        int8_t player = -1;       // -1: shared (the track map, the time left, GAME OVER)
        uint8_t group = 0;        // parts of one role and player in different elements (the message_* groups)
        bool present = true;      // false: built, but its callback hides it for good (another player's in a one
                                  // player race)
        bool frame = false;       // its bounds are its element's (the largest image: a panel or frame)
        Rect at;                  // where the game draws it (4:3, before the layout moves it): a still part's whole
                                  // image, cell or fill, a moving part's first place
        Rect reach;               // everywhere it can be drawn (at, for a part that doesn't move)
        Rect end;                 // a part that slides: where the slide ends (it moves from at to end in a straight
                                  // line, its element with it); invalid for one that doesn't
        Rect opaque;              // at shrunk to the image's opaque texels (a frame's bounds)
        // What the game builds it from (Image: an entry; Fill: a box), to find a widget's part.
        Identity id;
        // For drawing it without the game (tools/hud_preview).
        const char* texture = ""; // image name
        int16_t cell_w = 0, cell_h = 0, cell = 0;  // a cell of the image (0: the whole image): which one is drawn
        uint32_t color = 0;       // a fill's RGBA, or the text's
        std::string text;         // the text drawn for a Text part
        const char* note = "";    // how the game places it (the callback's rule)
    };

    // What decides which parts there are and where the game draws them.
    struct Variant {
        int players = 1;          // 1-4 (0x8010C3E2, players 3 and 4 copies of player 2's)
        int views = 1;            // the game's view count (0x8010C3EC): 1, or 2 for any split screen
        int language = 0;         // 0x800C4618: 0 English, 1 French, 2 German
        bool time_shown = true;   // the race time's HUD setting (the deaths count moves left without it)
    };

    // Every part for a variant, in the order the game draws them.
    std::vector<Part> parts(const Variant& v);

    // The part a widget was built as (an index into parts(v)), or -1.
    int find(const std::vector<Part>& parts, const Identity& id);

    // A texture's size and opaque texels (the ROM's), by name and language; nullptr if the catalog doesn't know it.
    struct Texture {
        const char* name;
        int8_t language;          // -1: the same in every language
        int16_t w, h;
        Rect opaque;              // in its own pixels (top row 0)
    };
    const Texture* texture(const char* name, int language);
}

#endif
